ALIGN_SOURCES = json.loads(zlib.decompress(base64.b64decode("")))
for name, content in ALIGN_SOURCES.items():
    (WORK / name).write_text(content, encoding="utf-8")
    SOURCES[name] = content
    manifest[name] = hashlib.sha256(content.encode()).hexdigest()
alignment_tests = subprocess.run([sys.executable, "-m", "unittest", "forge.test_tool_data", "forge.test_train_tools", "forge.test_distributed_tools"], cwd=WORK, text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
print(alignment_tests.stdout, flush=True)
assert alignment_tests.returncode == 0
RUN_V4 = ROOT / "runs/aligned-v4-150steps"
INIT_V4 = RUN_V3 / "adapter-step250"
assert not RUN_V4.exists()
assert hashlib.sha256(Path(str(INIT_V4)+".safetensors").read_bytes()).hexdigest() == "e36695151882767c51d75af41f31ea5230b8772a28a75c021700182690f8f5b9"
args_v4 = [sys.executable, "-u", "-m", "forge.train_tools", "--train", str(DATA_V3 / "train.jsonl"), "--validation", str(DATA_V3 / "validation.jsonl"), "--llm-dir", str(MODEL), "--out", str(RUN_V4), "--init-adapter", str(INIT_V4), "--languages", "en", "--steps", "150", "--batch", "1", "--accum", "8", "--max-length", "2048", "--rank", "16", "--alpha", "32", "--lr", "0.00005", "--gradient-checkpointing", "--checkpoint-every", "50", "--log-every", "25", "--max-runtime-minutes", "15"]
with subprocess.Popen(args_v4, cwd=WORK, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1) as process:
    for line in process.stdout:
        print(line, end="", flush=True)
    rc_v4 = process.wait()
assert rc_v4 == 0
(RUN_V4 / "source_manifest.json").write_text(json.dumps(manifest, indent=2))
(RUN_V4 / "base_revision.txt").write_text(revision)
(RUN_V4 / "environment.txt").write_text(subprocess.check_output([sys.executable, "-m", "pip", "freeze"], text=True))
print("ALIGNED V4 COMPLETE:", RUN_V4, flush=True)
